const out = [];
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    if (/html/i.test(p.name || '')) { continue; }
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase()
    }});
  }
}
return out;

const PER = 500;
const reqs = $('Build Count Requests').all();
const res = $input.all();
const out = [];
const failed = [];
const before = {};

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  const r = res[i].json || {};
  const hdr = r.headers || {};
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }
  before[meta.project_name] = total;
  if (total === 0) { continue; }
  const pages = Math.ceil(total / PER);
  for (let p = 1; p <= pages; p++) {
    out.push({ json: { project_id: meta.project_id, project_name: meta.project_name, base_lang: meta.base_lang, page: p } });
  }
}
for (const o of out) { o.json.failed = failed; o.json.count_before = before; }
if (out.length === 0) { out.push({ json: { project_id: null, page: 0, failed: failed, count_before: before } }); }
return out;

// ---- CONFIG -------------------------------------------------------------
// Empty PROJECT_ALLOW means every eligible project.
const PROJECT_ALLOW = [];
const INCLUDE_REVIEWED = true;   // Maria approved review-approved copy 2026-08-27 ("all")
// -------------------------------------------------------------------------

const PSEUDO = ['ps', 'pst'];
function isPseudo(iso) {
  const s = String(iso || '').toLowerCase();
  return PSEUDO.indexOf(s) !== -1 || s.indexOf('pseudo') !== -1;
}
function reject(s) {
  if (typeof s !== 'string' || s === '') { return 'empty'; }
  if (!/ {2,}/.test(s)) { return 'no_double_space'; }
  if (/[\u00A0\u202F\u2009\u200A\u2007\u2060\uFEFF]/.test(s)) { return 'nbsp_or_thin_space'; }
  if (/[<>&]/.test(s)) { return 'markup_or_entity'; }
  if (/[\n\r\t\v\f]/.test(s)) { return 'real_newline_or_tab'; }
  if (/\\[nrtvf]/.test(s)) { return 'escaped_newline'; }
  if (/^\s|\s$/.test(s)) { return 'edge_whitespace'; }
  if (/[%{}\[\]]/.test(s)) { return 'placeholder_char'; }
  if (s.indexOf('$t(') >= 0) { return 'i18n_call'; }
  return null;
}
function verify(before, after) {
  if (after === before) { return 'no_change'; }
  if (/ {2,}/.test(after)) { return 'still_has_double'; }
  if (before.replace(/ /g, '') !== after.replace(/ /g, '')) { return 'changed_non_space'; }
  if (before.length <= after.length) { return 'did_not_shrink'; }
  return null;
}

const reqs = $('Build Page Requests').all();
const res = $input.all();
const meta0 = (reqs[0] || { json: {} }).json;
const seenKey = {};
const out = [];
let rejected = 0;
let skippedReviewed = 0;
let outOfScope = 0;

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (!meta.project_id) { continue; }
  const r = res[i].json || {};
  if (r.statusCode !== 200) { continue; }

  for (const k of ((r.body && r.body.keys) ? r.body.keys : [])) {
    if (k.is_archived) { continue; }
    const dk = meta.project_id + '#' + k.key_id;
    if (seenKey[dk]) { continue; }
    seenKey[dk] = 1;

    for (const tr of (k.translations || [])) {
      const before = tr.translation;
      if (typeof before !== 'string') { continue; }
      const iso = String(tr.language_iso || '').toLowerCase();
      if (isPseudo(iso)) { continue; }
      if (iso === meta.base_lang) { continue; }
      if (reject(before)) { rejected++; continue; }
      const after = before.replace(/ {2,}/g, ' ');
      if (verify(before, after)) { rejected++; continue; }
      if (tr.is_reviewed && !INCLUDE_REVIEWED) { skippedReviewed++; continue; }
      if (PROJECT_ALLOW.length > 0 && PROJECT_ALLOW.indexOf(meta.project_name) === -1) { outOfScope++; continue; }

      let kn = k.key_name;
      if (kn && typeof kn === 'object') { kn = kn.web || kn.other || kn.ios || kn.android || String(k.key_id); }

      out.push({ json: {
        project_id: meta.project_id,
        project_name: meta.project_name,
        key: String(kn),
        translation_id: tr.translation_id,
        lang: iso,
        was_reviewed: tr.is_reviewed ? 1 : 0,
        before: before,
        after: after,
        count_before: meta0.count_before || {}
      }});
    }
  }
}
for (const o of out) { o.json.stats = { rejected: rejected, skipped_reviewed: skippedReviewed, out_of_scope: outOfScope, to_write: out.length }; }
if (out.length === 0) { out.push({ json: { project_id: null, project_name: null, translation_id: null, after: '', was_reviewed: 0, stats: { rejected: rejected, skipped_reviewed: skippedReviewed, out_of_scope: outOfScope, to_write: 0 }, count_before: meta0.count_before || {} } }); }
return out;

const intended = $('Select Write Scope').all();
const res = $input.all();
const ok = [];
const mismatch = [];
const errors = [];
const reviewLost = [];
let reviewedAttempted = 0;

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const want = (intended[idx] || intended[i] || { json: {} }).json;
  if (!want.translation_id) { continue; }
  const r = res[i].json || {};
  const body = r.body || {};
  const trObj = body.translation || null;
  const got = (trObj && typeof trObj.translation === 'string') ? trObj.translation : null;

  const rec = {
    project: want.project_name, lang: want.lang, key: want.key,
    translation_id: want.translation_id, status: r.statusCode,
    was_reviewed: want.was_reviewed || 0
  };
  if (want.was_reviewed) { reviewedAttempted++; }

  if (r.statusCode !== 200) {
    rec.error = JSON.stringify(body.error || body).slice(0, 200);
    errors.push(rec);
  } else if (got === null) {
    rec.error = 'no translation echoed back';
    errors.push(rec);
  } else if (got !== want.after) {
    rec.expected = want.after.slice(0, 120);
    rec.actual = got.slice(0, 120);
    mismatch.push(rec);
  } else {
    rec.is_reviewed_after = trObj.is_reviewed ? 1 : 0;
    if (want.was_reviewed && !trObj.is_reviewed) { reviewLost.push(rec); }
    ok.push(rec);
  }
}

const stats = (intended[0] || { json: {} }).json.stats || {};
return [{ json: {
  attempted: ok.length + mismatch.length + errors.length,
  written_and_verified: ok.length,
  mismatched: mismatch.length,
  failed: errors.length,
  reviewed_attempted: reviewedAttempted,
  review_flag_lost: reviewLost.length,
  scope_stats: stats,
  count_before: (intended[0] || { json: {} }).json.count_before || {},
  mismatch_rows: mismatch,
  error_rows: errors,
  review_lost_rows: reviewLost,
  written_rows: ok
}}];
